const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const longBeach = ee.Geometry.Point([-118.089042, 33.601421]);
  const pismoBeach = ee.Geometry.Point([-120.727924, 35.128348]);

  const targetDate = '2018-08-02';

  // 2. Data Acquisition
  // NOAA OISST V2.1 dataset with SST and climatology
  const oisst = ee.ImageCollection('NOAA/CDR/OISST/V2_1');

  // Get SST for target date
  const targetImg = oisst
    .filterDate('2018-08-02', '2018-08-03')
    .first();

  // Check if image exists
  const imgCount = oisst.filterDate('2018-08-02', '2018-08-03').size().getInfo();
  if (imgCount === 0) {
    console.log("No SST data for August 2, 2018.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Get long-term climatology for early August (day of year ~214)
  // Use a 7-day window around Aug 2 for climatology
  const climatology = oisst
    .filterDate('1981-07-30', '2017-08-05')
    .filter(ee.Filter.dayOfYear(213, 217))
    .select('sst')
    .mean();

  // 3. Calculate anomalies
  const sst = targetImg.select('sst');
  const anomaly = sst.subtract(climatology);

  // 4. Extract values at both locations
  const longBeachSST = sst.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: longBeach,
    scale: 27830,
    maxPixels: 1e9
  }).get('sst');

  const longBeachAnomaly = anomaly.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: longBeach,
    scale: 27830,
    maxPixels: 1e9
  }).get('sst');

  const pismoBeachSST = sst.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: pismoBeach,
    scale: 27830,
    maxPixels: 1e9
  }).get('sst');

  const pismoBeachAnomaly = anomaly.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: pismoBeach,
    scale: 27830,
    maxPixels: 1e9
  }).get('sst');

  const lbSST = await longBeachSST.getInfo();
  const lbAnom = await longBeachAnomaly.getInfo();
  const pbSST = await pismoBeachSST.getInfo();
  const pbAnom = await pismoBeachAnomaly.getInfo();

  // 5. Validation & Results
  console.log(`Long Beach - SST: ${lbSST !== null ? lbSST.toFixed(2) : 'null'} C, Anomaly: ${lbAnom !== null ? lbAnom.toFixed(2) : 'null'} C`);
  console.log(`Pismo Beach - SST: ${pbSST !== null ? pbSST.toFixed(2) : 'null'} C, Anomaly: ${pbAnom !== null ? pbAnom.toFixed(2) : 'null'} C`);

  if (lbAnom === null || pbAnom === null || lbSST === null || pbSST === null) {
    console.log("Missing or invalid SST data at one or both locations.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (isNaN(lbAnom) || isNaN(pbAnom)) {
    console.log("Calculation produced NaN values.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 6. Final Answer
  if (lbAnom > pbAnom) {
    console.log("Long Beach shows higher temperature anomaly.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Long Beach does not show higher temperature anomaly.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
